def solve():
    n = int(input())
    arr = list(map(int, input().split()))
    if len(arr) != n:
        print('input length mismatch')
        return
    counts = {}
    for x in arr:
        if x in counts:
            counts[x] += 1
        else:
            counts[x] = 1
    max_count = 0
    max_val = None
    for k, v in counts.items():
        if v > max_count:
            max_count = v
            max_val = k
        elif v == max_count and k < max_val:
            max_val = k
    if max_count == 1:
        print('no mode')
    else:
        print(max_val)

